import { Component, Element, Host, Prop, h } from "@stencil/core";

const VARIANT_PROPS = {
	page: {
		display: "flex",
		direction: "column",
		gap: "none",
		align: "stretch",
		justify: "start",
	},
	"page:header": {
		display: "flex",
		direction: "column",
		gap: "2xs",
		align: "stretch",
		justify: "start",
	},
	// Footer variant
	"page:footer": {
		display: "flex",
		direction: "row",
		gap: "md",
		align: "center",
		justify: "space-between",
	},
	// Form variants
	form: {
		display: "flex",
		direction: "column",
		gap: "md",
		align: "stretch",
		justify: "start",
	},
	"form:section": {
		display: "flex",
		direction: "column",
		gap: "lg",
		align: "start",
		justify: "start",
	},
	"form:section:header": {
		display: "flex",
		direction: "column",
		gap: "xs",
		align: "stretch",
		justify: "start",
	},
	"form:section:body": {
		display: "flex",
		direction: "column",
		gap: "md",
		align: "stretch",
		justify: "start",
	},
	"form:field": {
		display: "grid",
		direction: "row",
		gap: "md",
		align: "start",
		justify: "start",
	},
	// Dashboard variants
	dashboard: {
		display: "flex",
		direction: "column",
		gap: "lg",
		align: "stretch",
		justify: "start",
	},
	"dashboard:section": {
		display: "flex",
		direction: "column",
		gap: "md",
		align: "stretch",
		justify: "start",
	},
	"dashboard:widgets:basic-statistics": {
		display: "grid",
		direction: "row",
		gap: "sm",
		align: "stretch",
		justify: "start",
	},
	"dashboard:widgets:basic-health": {
		display: "grid",
		direction: "row",
		gap: "sm",
		align: "stretch",
		justify: "start",
	},
	"dashboard:widgets:basic-health:status": {
		display: "flex",
		direction: "column",
		gap: "none",
		align: "start",
		justify: "start",
	},
	"dashboard:widgets:basic-status": {
		display: "grid",
		direction: "row",
		gap: "md",
		align: "stretch",
		justify: "start",
	},
	"dashboard:widgets:content": {
		display: "grid",
		direction: "row",
		gap: "md",
		align: "stretch",
		justify: "start",
	},
	"dashboard:widgets:container": {
		display: "grid",
		direction: "row",
		gap: "md",
		align: "stretch",
		justify: "start",
	},
} as const;

const DEFAULTS = {
	display: "flex",
	direction: "row",
	gap: "md",
	justify: "start",
} as const;

/**
 * Semantic layout primitive for structuring UI blocks.
 *
 * Provides flex and grid layouts with consistent spacing and alignment.
 * Use semantic variants for common page patterns (page, form, dashboard),
 * or set primitive props (display, direction, gap, align) for custom layouts.
 *
 * Variants configure layout presets - explicit props override variant defaults.
 *
 * @since 2.18.10
 * @status beta
 *
 * @slot - Layout children elements.
 *
 * @example
 * // Page structure with semantic variants
 * <hbr-layout variant="page">
 *   <hbr-layout variant="page:header">...</hbr-layout>
 *   <hbr-layout variant="page:footer">...</hbr-layout>
 * </hbr-layout>
 *
 * @example
 * // Dashboard with widget grids
 * <hbr-layout variant="dashboard">
 *   <hbr-layout variant="dashboard:widgets:basic-statistics">...</hbr-layout>
 *   <hbr-layout variant="dashboard:widgets:container">...</hbr-layout>
 * </hbr-layout>
 *
 * @example
 * // Form section structure
 * <hbr-layout variant="form:section">
 *   <hbr-layout variant="form:section:header">...</hbr-layout>
 *   <hbr-layout variant="form:section:body">...</hbr-layout>
 * </hbr-layout>
 *
 * @example
 * // Custom layout with primitives
 * <hbr-layout direction="column" gap="lg" align="stretch">...</hbr-layout>
 */
@Component({
	tag: "hbr-layout",
	styleUrl: "layout.scss",
	scoped: false,
})
export class Layout {
	@Element() el: HTMLHbrLayoutElement;

	/**
	 * Semantic layout variant for common UI patterns.
	 * Variants follow hierarchy: domain:scope:category (e.g., dashboard:widgets:basic-statistics).
	 */
	@Prop({ reflect: true }) variant:
		| "page"
		| "page:header"
		| "page:footer"
		| "form"
		| "form:section"
		| "form:section:header"
		| "form:section:body"
		| "form:field"
		| "dashboard"
		| "dashboard:section"
		| "dashboard:widgets:basic-statistics"
		| "dashboard:widgets:basic-health"
		| "dashboard:widgets:basic-health:status"
		| "dashboard:widgets:basic-status"
		| "dashboard:widgets:content"
		| "dashboard:widgets:container";

	/** Display mode: 'flex' for linear layouts, 'grid' for widget grids. */
	@Prop() display: "flex" | "grid";

	/** Main axis direction for flex layouts. */
	@Prop() direction: "row" | "column";

	/** Spacing between child elements using design token scale. */
	@Prop() gap: "none" | "2xs" | "xs" | "sm" | "md" | "lg" | "xl" | "2xl";

	/** Cross-axis alignment of child elements. */
	@Prop() align: "stretch" | "start" | "center" | "end" | "baseline";

	/** Main-axis distribution of child elements. */
	@Prop() justify:
		| "start"
		| "center"
		| "end"
		| "space-between"
		| "space-around"
		| "space-evenly";

	componentWillRender() {
		const variantProps = this.variant ? VARIANT_PROPS[this.variant] : null;

		const finalDisplay =
			this.display || variantProps?.display || DEFAULTS.display;
		const finalDirection =
			this.direction || variantProps?.direction || DEFAULTS.direction;
		const finalGap = this.gap || variantProps?.gap || DEFAULTS.gap;

		// Smart align default: stretch for grid/column, center for flex-row
		const getDefaultAlign = () => {
			if (finalDisplay === "grid") return "stretch";
			return finalDirection === "column" ? "stretch" : "center";
		};
		const finalAlign = this.align || variantProps?.align || getDefaultAlign();
		const finalJustify =
			this.justify || variantProps?.justify || DEFAULTS.justify;

		this.el.setAttribute("display", finalDisplay);
		this.el.setAttribute("direction", finalDirection);
		this.el.setAttribute("gap", finalGap);
		this.el.setAttribute("align", finalAlign);
		this.el.setAttribute("justify", finalJustify);
	}

	render() {
		return <Host />;
	}
}
